(x, y, t) => {
  const s = t * 0.3;
  const nx = x / 90, ny = y / 90;
  const w1 = Math.sin(nx * 3.7 + ny * 2.3 + s * 0.6);
  const w2 = Math.sin(nx * 2.1 - ny * 3.9 - s * 0.4);
  const w3 = Math.cos(nx * 4.3 + ny * 1.1 + s * 0.8);
  const w4 = Math.cos(nx * 1.7 + ny * 4.7 - s * 0.5);
  const w5 = Math.sin((nx + ny) * 2.9 + s * 0.3);
  const w6 = Math.cos((nx - ny) * 3.3 - s * 0.7);
  let A = (w1 + w3 + w5) * 0.333;
  let B = (w2 + w4 + w6) * 0.333;
  const ab = A * B, a2 = A * A, b2 = B * B;
  A += 0.12 * (-ab + a2 * 0.3 - A * a2 * 0.1);
  B += 0.12 * (ab - b2 * 0.3 + B * b2 * 0.1);
  const d = Math.sqrt((nx - 2.5) * (nx - 2.5) + (ny - 1.5) * (ny - 1.5));
  const radial = Math.sin(d * 4.0 - s * 1.2) * Math.exp(-d * 0.15);
  const C = Math.sin(A * B * 5.0 + s * 0.2) * 0.5 + radial;
  const na = A * 0.5 + 0.5, nb = B * 0.5 + 0.5, nc = C * 0.5 + 0.5;
  const r = na * 0.55 + nb * 0.3 + nc * 0.25;
  const g = na * 0.3 + nb * 0.5 + nc * 0.15;
  const b = na * 0.2 + nb * 0.15 + nc * 0.6;
  const tm = 0.9;
  return [
    Math.pow(Math.min(Math.max(r, 0), 1), tm),
    Math.pow(Math.min(Math.max(g, 0), 1), tm),
    Math.pow(Math.min(Math.max(b, 0), 1), tm)
  ];
}
